const {accel, mag, heading, temperature} = msg.payload;
const points = ['N','NNE','NE','ENE','E','ESE','SE','SSE','S','SSW','SW','WSW','W','WNW','NW','NNW'];
const idx = Math.floor((heading + 11.25) / 22.5) % 16;
const roll = Math.atan2(accel.y, accel.z) * 180 / Math.PI;
const pitch = Math.atan2(-accel.x, Math.hypot(accel.y, accel.z)) * 180 / Math.PI;
msg.payload = {
    heading: heading,
    point: points[idx],
    pitch: pitch,
    roll: roll,
    temperature: temperature
};
return msg;
